function validate([position]) {
  if (!Array.isArray(position) || position.length < 1 || position.length > 100) return 'position needs 1 to 100 values.';
  if (position.some(p => !Number.isInteger(p) || p < 1 || p > 1000000000)) return 'Each position is an integer from 1 to 10^9.';
  return null;
}

