function minCostToMoveChips(position) {
  // Try every chip's spot and the spot next to the first chip as the meeting point.
  // A chip that is d away needs floor(d / 2) free jumps and d % 2 paid steps.
  const targets = [...position, position[0] + 1];
  let answer = Infinity;
  for (const target of targets) {
    let total = 0;
    for (const p of position) {
      const distance = Math.abs(p - target);
      total += distance - 2 * Math.floor(distance / 2);
    }
    answer = Math.min(answer, total);
  }
  return answer;
}

