function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' || rand() < 0.2 ? 1000000000 : 10;
  const position = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [position];
}
